CustomField.formula:
IF(OR(Subsidy_Amount_Paid__c = 0,ISPICKVAL(Improper_Payment__c , 'N')), 1,
            IF(Subsidy_Amount_Paid__c = Correct_Subsidy_Amount__c, 1,
            IF(AND(Correct_Subsidy_Amount__c = 0,ISPICKVAL(Improper_Payment__c , 'Y')), 0,
IF(Subsidy_Amount_Paid__c > Correct_Subsidy_Amount__c,
  Correct_Subsidy_Amount__c / Subsidy_Amount_Paid__c,
  Subsidy_Amount_Paid__c / Correct_Subsidy_Amount__c)
  )
            )
)
